static void put_json_parse(FILE * f, const char * s) {
    for (; (*s); s++) {
        if ((((*s) == '"') || ((*s) == '\\'))) {
            fputc('\\', f);
            fputc((*s), f);
        }
        else {
            if ((*s) == '\n') {
                fputs("\\n", f);
            }
            else {
                if ((*s) == '\t') {
                    fputs("\\t", f);
                }
                else {
                    if ((unsigned char)((*s)) < 32) {
                        fputc('?', f);
                    }
                    else {
                        fputc((*s), f);
                    }
                }
            }
        }
    }
}
